import com.infinitylibrary.InfinityLibraryPlugin;import com.infinitylibrary.model.*;import org.bukkit.*;import java.util.*;
/** Fresh install/migration checks on a real disposable Paper world. */
public class ReleaseSmoke extends LibraryProbe {
 @Override public void onEnable(){later(()->{var p=(InfinityLibraryPlugin)Bukkit.getPluginManager().getPlugin("InfinityLibraryPlugin");var e=p.getGenerationEngine();check(p.getDescription().getVersion().equals("4.0.1"),"release reports version 4.0.1");check(!p.getConfig().getBoolean("builder.legacy-companion-enabled"),"client companion transport disabled by default");check(Bukkit.getMessenger().getIncomingChannels(p).isEmpty(),"server-only release registers no client companion channel");check(p.getConfig().getInt("generation.schema")==4,"legacy configuration migrated to schema 4");check(p.getConfig().getString("generation.base-room-id").isBlank(),"old default modular restriction migrated to mixed catalog");check(e.placedCount()==1&&e.queuedBlocks()==0,"fresh entrance finishes without manual generation");check(e.eligibleTemplates()>=10,"full shipped catalog is available to district planning");var f=new Fake(p,true);f.position=e.homeLocation();int before=e.placedCount();e.checkExplorers(List.of(f.player));check(e.placedCount()>before,"fresh mixed catalog expands automatically near entrance");check(e.futurePlanCount()>0,"mixed catalog reserves multiple future generations");later(()->{check(e.queuedBlocks()==0,"mixed catalog construction completes");check(e.openExitCount()>0,"automatic district preserves a growth frontier");int future=e.futurePlanCount();p.reloadEverything();check(e.futurePlanCount()==future,"mixed catalog district survives full reload");getLogger().info("ALL "+count+" RELEASE SMOKE CHECKS PASSED");Bukkit.shutdown();},120);},200);}
}
